harbor:
/* Harbor — Seal Blue and Navy, with a little Crimson Pink.
   Dockside poster: big condensed type, a pink waterline, flags flying.
   Colors: #3e6a8a seal blue · #0b1733 navy · #e8336d crimson pink. */
:root {
  --bg: #0b1733;
  --panel: #3e6a8a;
  --panel-2: #13244a;
  --text: #f1f4fa;
  --muted: #93a6c4;
  --accent: #e8336d;
  --accent-text: #fff;
  --line: #1c2f58;
  --radius: 14px;
  --font: "Avenir Next", Avenir, "Segoe UI", system-ui, sans-serif;
  --wordmark: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
  --display: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
  --msg-size: 15px;
}

/* Sidebar: seal blue, with a pink waterline down its edge */
.sidebar { border-right: 4px solid var(--accent); }
.sidebar .brand, .sidebar .foot { border-color: rgba(11, 23, 51, 0.25); }
.wordmark { font-family: var(--display); font-style: italic; font-weight: 400; color: #fff; letter-spacing: 0.01em; }
.wordmark.small { font-size: 46px; line-height: 0.9; text-shadow: 3px 3px 0 #0b1733; }
.me-line { color: rgba(255, 255, 255, 0.75); }
.me-line b { color: #fff; }
.space-name { color: #0b1733; font-weight: 700; letter-spacing: 0.16em; }
.space li { color: rgba(255, 255, 255, 0.85); border-radius: 999px; padding: 6px 12px; font-weight: 500; }
.space li:hover { background: rgba(11, 23, 51, 0.2); color: #fff; }
.space li.active { background: #0b1733; color: #fff; font-weight: 700; box-shadow: inset 4px 0 0 var(--accent); }
.space li .dot { background: var(--accent); }
.new-room input { color: #fff; }
.new-room input::placeholder { color: rgba(255, 255, 255, 0.6); }
.sidebar .foot input, .sidebar .foot select { background: rgba(11, 23, 51, 0.3); border-color: transparent; color: #fff; }
.sidebar .foot input::placeholder { color: rgba(255, 255, 255, 0.6); }
.sidebar .foot button.ghost { color: #fff; }

/* Room: navy water, faint swell lines at the bottom */
.messages {
  background:
    repeating-radial-gradient(ellipse 140% 60% at 50% 140%, transparent 0 22px, rgba(62, 106, 138, 0.10) 22px 24px) bottom / 100% 240px no-repeat,
    var(--bg);
}
.room-head { border-bottom: 0; padding-top: 16px; }
.room-title > div:first-child { font-family: var(--display); font-weight: 400; font-size: 34px; line-height: 1; text-transform: uppercase; letter-spacing: 0.01em; }
.room-title .hash { color: var(--accent); }
.room-sub { margin-top: 6px; }
.no-room h2 { font-family: var(--display); font-style: normal; font-weight: 400; text-transform: uppercase; font-size: 54px; line-height: 0.95; }

.day { display: flex; align-items: center; gap: 12px; letter-spacing: 0.2em; font-size: 11px; font-weight: 700; color: var(--accent); }
.day::before, .day::after { content: ""; flex: 1; height: 1px; background: var(--line); }

.name { color: #fff; }
.body a { color: #ff7aa2; }
.avatar, .avatar > img { border-radius: 50%; }

/* Files: a white shipping tag with a pink stripe */
.file { background: #f1f4fa; color: #0b1733; border: 0; box-shadow: inset 5px 0 0 var(--accent); }
.file .file-sub { color: #4b5e80; }
.file .bar { background: rgba(11, 23, 51, 0.12); }
.file.gone { background: transparent; color: var(--text); border: 1px dashed var(--line); box-shadow: none; }

button { border-radius: 999px; }
button:not(.ghost):not(.secondary):not(.me-line) { font-family: var(--display); font-weight: 400; text-transform: uppercase; letter-spacing: 0.06em; font-size: 16px; }
.file .file-act button, .room-actions button, .ttl button, #memberList li button { font-size: 13px; }
.composer { border-top: 0; }
.composer textarea { background: var(--panel-2); border: 2px solid transparent; border-radius: 22px; padding: 11px 18px; }
.composer textarea:focus { border-color: var(--accent); }
.composer button[type="submit"] { padding: 10px 26px; font-size: 19px; box-shadow: 3px 3px 0 #3e6a8a; }

indigo-mint:
/* Indigo Mint — Onyx Black and Electric Indigo, with one touch of Tropical Mint.
   Studio-lit poster: heavy condensed type, a fancy italic, indigo light
   spilling in from the corner.
   Colors: #01010D onyx · #6331FB electric indigo · #88F9C0 tropical mint. */
:root {
  --bg: #01010d;
  --panel: #6331fb;
  --panel-2: #14122a;
  --text: #f4f2ff;
  --muted: #9a95c4;
  --accent: #88f9c0;
  --accent-text: #01010d;
  --line: #1d1a3a;
  --radius: 14px;
  --font: "Avenir Next", Avenir, "Segoe UI", system-ui, sans-serif;
  --wordmark: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
  --display: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
  --fancy: Didot, "Bodoni 72", "Bodoni MT", "Playfair Display", Georgia, serif;
  --msg-size: 15px;
}

/* Sidebar: a slab of electric indigo */
.sidebar { border-right: 0; background: linear-gradient(170deg, #7446ff 0%, #6331fb 45%, #4a1fd6 100%); }
.sidebar .brand, .sidebar .foot { border-color: rgba(255, 255, 255, 0.14); }
.wordmark { font-family: var(--display); font-style: italic; font-weight: 400; color: #fff; letter-spacing: 0.01em; }
.wordmark.small { font-size: 46px; line-height: 0.9; }
.me-line { color: rgba(255, 255, 255, 0.7); }
.me-line b { color: #fff; }
.space-name { color: rgba(255, 255, 255, 0.62); font-weight: 700; letter-spacing: 0.18em; }
.space li { color: rgba(255, 255, 255, 0.82); border-radius: 999px; padding: 6px 12px; font-weight: 500; }
.space li:hover { background: rgba(1, 1, 13, 0.18); color: #fff; }
.space li.active { background: var(--accent); color: #01010d; font-weight: 700; }
.space li.unread { color: #fff; }
.space li .dot { background: var(--accent); }
.new-room input { color: #fff; }
.new-room input::placeholder { color: rgba(255, 255, 255, 0.55); }
.sidebar .foot input, .sidebar .foot select { background: rgba(1, 1, 13, 0.28); border-color: transparent; color: #fff; }
.sidebar .foot input::placeholder { color: rgba(255, 255, 255, 0.6); }
.sidebar .foot button.ghost { color: #fff; }

/* Room: black, with indigo studio light from the top right */
.room { background: radial-gradient(ellipse 70% 60% at 100% 0%, rgba(99, 49, 251, 0.42), transparent 70%), var(--bg); }
.messages, .room-head { background: transparent; }
.room-head { border-bottom: 0; padding-top: 16px; }
.room-title > div:first-child { font-family: var(--display); font-weight: 400; font-size: 34px; line-height: 1; text-transform: uppercase; letter-spacing: 0.01em; }
.room-title .hash { font-family: var(--fancy); font-style: italic; font-weight: 400; text-transform: none; color: var(--accent); margin-right: 6px; }
.room-sub { margin-top: 6px; }
.no-room h2 { font-family: var(--fancy); font-style: italic; font-weight: 400; font-size: 48px; color: #fff; }

.day { display: flex; align-items: center; justify-content: center; gap: 14px; letter-spacing: 0.32em; font-size: 10px; font-weight: 700; color: var(--muted); }
.day::before, .day::after { content: ""; width: 40px; height: 1px; background: var(--muted); opacity: 0.6; }

.name { color: #fff; }
.body a { color: var(--accent); }
.avatar, .avatar > img { border-radius: 50%; }

/* Files: frosted indigo card, mint button */
.file { background: rgba(99, 49, 251, 0.18); border: 1px solid rgba(136, 249, 192, 0.18); backdrop-filter: blur(8px); }
.file .bar span { background: var(--accent); }
.file .file-act button { background: var(--accent); color: #01010d; }
.file.gone { background: transparent; border: 1px dashed var(--line); }

/* Buttons: mint pills with tracked lettering and an arrow */
button { border-radius: 999px; }
button:not(.ghost):not(.secondary):not(.me-line) { text-transform: uppercase; letter-spacing: 0.12em; font-size: 12px; font-weight: 700; }
.composer { border-top: 0; }
.composer textarea { background: rgba(20, 18, 42, 0.85); border: 1px solid var(--line); border-radius: 22px; padding: 11px 18px; }
.composer textarea:focus { border-color: var(--accent); }
.composer button[type="submit"] { padding: 10px 20px; box-shadow: 0 0 24px rgba(136, 249, 192, 0.25); }
.composer button[type="submit"]::after { content: "  →"; }

marshmallow:
/* Marshmallow — Marshmallow White and Galactic Violet, with Bubblegum Pink.
   Clean white lab, a violet-to-pink glow rising from the corner,
   glass cards, black pill for where you are.
   Colors: #F0F0F0 marshmallow · #5B3BFF galactic violet · #E96BD8 bubblegum.
   (The reel's labels for the last two didn't match their swatches,
   so these are matched to the swatches by eye.) */
:root {
  --bg: #f0f0f0;
  --panel: rgba(255, 255, 255, 0.55);
  --panel-2: rgba(255, 255, 255, 0.8);
  --text: #111118;
  --muted: #7b7b8e;
  --accent: #5b3bff;
  --accent-text: #fff;
  --line: rgba(17, 17, 24, 0.08);
  --radius: 16px;
  --font: "Avenir Next", Avenir, "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
  --wordmark: "Avenir Next", Avenir, "Segoe UI Variable Display", "Segoe UI", sans-serif;
  --msg-size: 15px;
}

/* The glow: violet and pink rising from the bottom-left */
body {
  background:
    radial-gradient(ellipse 55% 45% at 0% 100%, rgba(233, 107, 216, 0.55), transparent 70%),
    radial-gradient(ellipse 50% 40% at 30% 105%, rgba(91, 59, 255, 0.45), transparent 70%),
    radial-gradient(ellipse 50% 50% at 70% 30%, #ffffff, transparent 70%),
    #f0f0f0;
  background-attachment: fixed;
}

/* Frosted glass */
.sidebar, .members, .search, .pending, .dialog {
  background: rgba(255, 255, 255, 0.5);
  -webkit-backdrop-filter: blur(24px) saturate(1.3); backdrop-filter: blur(24px) saturate(1.3);
  border-color: rgba(255, 255, 255, 0.9);
}
.sidebar .brand, .sidebar .foot { border-color: var(--line); }

/* Type: light capitals, tight, like a lab readout */
.wordmark { font-family: var(--wordmark); font-style: italic; font-weight: 300; letter-spacing: -0.02em; color: var(--text); }
.wordmark.small { font-size: 34px; line-height: 1; }
.wordmark.small::after { content: ""; display: inline-block; width: 26px; height: 8px; margin-left: 8px; vertical-align: middle; background: repeating-linear-gradient(115deg, var(--accent) 0 3px, transparent 3px 6px); }
.room-head { border-bottom: 0; padding-top: 18px; }
.room-title > div:first-child { font-weight: 300; font-size: 30px; text-transform: uppercase; letter-spacing: -0.02em; line-height: 1.05; }
.room-title .hash { color: var(--accent); font-weight: 300; }
.no-room h2 { font-family: var(--wordmark); font-style: normal; font-weight: 300; text-transform: uppercase; font-size: 40px; letter-spacing: -0.02em; }
.space-name, .day { font-size: 10px; letter-spacing: 0.22em; font-weight: 600; color: var(--muted); }
.day { display: flex; align-items: center; justify-content: center; gap: 14px; }
.day::before, .day::after { content: ""; width: 36px; height: 1px; background: currentColor; opacity: 0.4; }

/* Rooms list: a black pill for where you are */
.space li { border-radius: 999px; padding: 6px 12px; color: #4a4a5c; }
.space li:hover { background: rgba(255, 255, 255, 0.85); color: var(--text); }
.space li.active { background: #111118; color: #fff; font-weight: 600; }
.space li.active .live { background: #fff; }
.space li .dot { background: #e96bd8; }

.messages { background: transparent; }
.name { font-weight: 700; }
.body a { color: var(--accent); }
.avatar, .avatar > img { border-radius: 50%; }
.avatar { box-shadow: 0 0 0 2px #fff, 0 4px 12px rgba(91, 59, 255, 0.18); }

/* Cards and inputs: white glass */
.file, .composer textarea, .sidebar .foot input, .sidebar .foot select {
  background: rgba(255, 255, 255, 0.62);
  -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.95);
  box-shadow: 0 8px 28px rgba(17, 17, 24, 0.06);
}
.file { border-radius: 20px; }
.file .bar span { background: linear-gradient(90deg, #5b3bff, #e96bd8); }
.file.gone { background: transparent; border: 1px dashed rgba(17, 17, 24, 0.2); box-shadow: none; }
.composer { border-top: 0; }
.composer textarea { border-radius: 24px; padding: 12px 18px; }
.composer textarea:focus { border-color: var(--accent); }

/* Buttons: violet-to-pink pills; quiet ones outlined */
button { border-radius: 999px; }
button:not(.ghost):not(.secondary):not(.me-line) { background: linear-gradient(100deg, #5b3bff, #e96bd8); box-shadow: 0 8px 22px rgba(91, 59, 255, 0.28); }
button.secondary { background: transparent; border: 1px solid rgba(17, 17, 24, 0.2); color: var(--text); }
.composer button[type="submit"] { padding: 11px 24px; }
.scrim { background: rgba(17, 17, 24, 0.2); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
.toast { background: #111118; color: #fff; }

necklace:
/* Necklace — Lake Merritt after dark.
   Ink-blue water, and the string of lights around the lake hung across
