/* Room: forest green with a soft yellow sun rising in the corner */
.messages {
  background:
    radial-gradient(circle at 105% 108%, rgba(224, 243, 84, 0.10) 0 260px, transparent 261px),
    radial-gradient(circle at 105% 108%, rgba(253, 85, 10, 0.08) 0 380px, transparent 381px),
    var(--bg);
}
.room-head { border-bottom: 0; padding-top: 16px; }
.room-title > div:first-child { font-family: var(--display); font-weight: 400; font-size: 34px; line-height: 1; text-transform: uppercase; color: var(--accent); letter-spacing: 0.01em; }
.room-title .hash { color: #fd550a; }
.room-sub { color: var(--muted); margin-top: 6px; }
.no-room h2 { font-family: var(--display); font-style: normal; font-weight: 400; text-transform: uppercase; font-size: 54px; line-height: 0.95; color: var(--accent); }

.day { display: flex; align-items: center; gap: 12px; color: var(--accent); font-weight: 700; letter-spacing: 0.18em; font-size: 11px; }
.day::before, .day::after { content: ""; flex: 1; height: 2px; background: rgba(224, 243, 84, 0.25); }

.name { color: var(--accent); }
.body a { color: var(--accent); }
.avatar, .avatar > img { border-radius: 50%; }

/* Files: a cream label with an orange button */
.file { background: #fff6e6; color: #013a2c; border: 0; }
.file .file-sub { color: #3d6b5c; }
.file .file-act button { background: #fd550a; color: #fff6e6; }
.file .bar { background: rgba(1, 58, 44, 0.15); }
.file .bar span { background: #fd550a; }
.file.gone { background: transparent; color: var(--text); border: 2px dashed rgba(255, 246, 230, 0.3); }
.file.gone .file-sub { color: var(--muted); }

/* Buttons: big yellow pills, poster lettering */
button { border-radius: 999px; }
button:not(.ghost):not(.secondary):not(.me-line) { font-family: var(--display); font-weight: 400; text-transform: uppercase; letter-spacing: 0.06em; font-size: 16px; }
.file .file-act button, .room-actions button, .ttl button, #memberList li button { font-size: 13px; }
.composer { border-top: 0; }
.composer textarea { background: var(--panel-2); border: 2px solid transparent; border-radius: 22px; padding: 11px 18px; }
.composer textarea:focus { border-color: var(--accent); }
.composer button[type="submit"] { padding: 10px 26px; font-size: 19px; box-shadow: 3px 3px 0 #fd550a; }

showfile:
/* Showfile — the lighting console at front of house. Matte black, yellow
   readouts, and every message gets a cue number down the left. */
:root {
  --bg: #1a1b1d;
  --panel: #121315;
  --panel-2: #26282b;
  --text: #d9d4c7;
  --muted: #7f7b72;
  --accent: #ffc400;
  --accent-text: #1a1400;
  --line: #2e3034;
  --radius: 3px;
  --font: "DIN Alternate", Bahnschrift, "Arial Narrow", system-ui, sans-serif;
  --mono: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  --wordmark: "DIN Condensed", "Bahnschrift Condensed", "Arial Narrow", sans-serif;
}

.wordmark { font-style: normal; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; }
.wordmark.small { font-size: 22px; }

/* The room name reads like the console's display. */
.room-head { background: #0d0e0f; }
.room-title > div:first-child { font-family: var(--mono); color: var(--accent); letter-spacing: 0.06em; font-size: 16px; }
.hash { color: var(--muted); }

/* Cue numbers. */
.messages { counter-reset: cue; }
.msg { position: relative; padding-left: 52px; }
.msg:not(.cont) { counter-increment: cue; }
.msg:not(.cont)::before {
  content: "Q" counter(cue); position: absolute; left: 0; top: 2px; width: 44px;
  font-family: var(--mono); font-size: 12px; color: var(--accent); text-align: right;
}
.time { font-family: var(--mono); font-size: 11px; }
.avatar { border-radius: 3px; }

.space li.active { background: transparent; color: var(--accent); box-shadow: inset 3px 0 0 var(--accent); border-radius: 0; }
.space li .live { box-shadow: 0 0 6px #3fcf7f; }
.composer textarea { font-family: var(--mono); font-size: 14px; }
.day, .note { font-family: var(--mono); font-size: 11px; letter-spacing: 0.04em; }

terminal:
/* Terminal — green on black, square corners, all monospace.
   A good example of going beyond colors: you can restyle anything. */
:root {
  --bg: #050805;
  --panel: #0a100a;
  --panel-2: #101a10;
  --text: #9cff9c;
  --muted: #3f8a3f;
  --accent: #33ff66;
  --accent-text: #000000;
  --line: #1c2e1c;
  --radius: 0px;
  --font: var(--mono);
  --wordmark: var(--mono);
  --msg-size: 14px;
}
.avatar { border-radius: 0; filter: grayscale(1) brightness(1.4); }
.wordmark::before { content: "> "; }

visionary:
/* Visionary — Seal Blue and Navy, with Crimson Pink.
   The "premium" look: a soft sky gradient, frosted glass panels,
   light big type with an italic kick, pink pill buttons.
   Colors: #DBF2FC seal blue · #072D59 navy · #FD6E88 crimson pink. */
:root {
  --bg: #eaf7fd;
  --panel: rgba(255, 255, 255, 0.5);
  --panel-2: rgba(255, 255, 255, 0.7);
  --text: #072d59;
  --muted: #5d7899;
  --accent: #fd6e88;
  --accent-text: #fff;
  --line: rgba(7, 45, 89, 0.1);
  --radius: 16px;
  --font: "Avenir Next", Avenir, "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
  --wordmark: "Avenir Next", Avenir, "Segoe UI Variable Display", "Segoe UI", sans-serif;
  --msg-size: 15px;
}

/* The sky: seal blue up top, a pink haze, navy deep in the corner */
body {
  background:
    radial-gradient(ellipse 45% 55% at 100% 100%, rgba(7, 45, 89, 0.55), transparent 70%),
    radial-gradient(ellipse 35% 45% at 88% 70%, rgba(253, 110, 136, 0.28), transparent 70%),
    radial-gradient(ellipse 60% 50% at 20% 0%, #ffffff, transparent 70%),
    linear-gradient(180deg, #dbf2fc 0%, #e4f3fb 50%, #c9def0 100%);
  background-attachment: fixed;
}

/* Frosted glass */
.sidebar, .members, .search, .pending, .dialog {
  background: rgba(255, 255, 255, 0.42);
  -webkit-backdrop-filter: blur(24px) saturate(1.4); backdrop-filter: blur(24px) saturate(1.4);
  border-color: rgba(255, 255, 255, 0.75);
}
.sidebar .brand, .sidebar .foot { border-color: rgba(7, 45, 89, 0.08); }

/* Type: light and big, with an italic kick */
.wordmark { font-family: var(--wordmark); font-style: italic; font-weight: 200; letter-spacing: -0.03em; color: var(--text); }
.wordmark.small { font-size: 38px; line-height: 1; }
.room-head { border-bottom: 0; padding-top: 18px; }
.room-title > div:first-child { font-weight: 300; font-size: 32px; letter-spacing: -0.02em; line-height: 1.05; }
.room-title .hash { font-style: italic; font-weight: 700; color: var(--accent); margin-right: 4px; }
.no-room h2 { font-family: var(--wordmark); font-style: italic; font-weight: 600; font-size: 40px; letter-spacing: -0.02em; }
.space-name, .day { font-size: 10px; letter-spacing: 0.24em; font-weight: 600; color: var(--muted); }
.day { display: flex; align-items: center; justify-content: center; gap: 14px; }
.day::before, .day::after { content: ""; width: 36px; height: 1px; background: currentColor; opacity: 0.5; }

/* Rooms list: navy pill for where you are */
.space li { border-radius: 999px; padding: 6px 12px; color: #3c5a7e; }
.space li:hover { background: rgba(255, 255, 255, 0.7); color: var(--text); }
.space li.active { background: var(--text); color: #fff; font-weight: 600; box-shadow: 0 6px 18px rgba(7, 45, 89, 0.25); }
.space li.active .live { background: #fff; }

.messages { background: transparent; }
.name { color: var(--text); font-weight: 700; }
.body a { color: #d94a66; }
.avatar, .avatar > img { border-radius: 50%; }

/* Cards and inputs: glass with a white edge and a soft shadow */
.file, .composer textarea, .sidebar .foot input, .sidebar .foot select {
  background: rgba(255, 255, 255, 0.55);
  -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.9);
  box-shadow: 0 8px 28px rgba(7, 45, 89, 0.08);
}
.file { border-radius: 20px; }
.file.gone { background: transparent; border: 1px dashed rgba(7, 45, 89, 0.25); box-shadow: none; }
.composer { border-top: 0; }
.composer textarea { border-radius: 24px; padding: 12px 18px; }
.composer textarea:focus { border-color: var(--accent); }

/* Buttons: pink pills that glow a little; quiet ones are outlined */
button { border-radius: 999px; }
button:not(.ghost):not(.secondary):not(.me-line) { box-shadow: 0 8px 20px rgba(253, 110, 136, 0.35); }
button.secondary { background: transparent; border: 1px solid rgba(7, 45, 89, 0.25); color: var(--text); }
.composer button[type="submit"] { padding: 11px 24px; }
.scrim { background: rgba(7, 45, 89, 0.25); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
.toast { background: var(--text); color: #fff; }
